const char *quanta_metric_documentation(const char *key) {
#if QUANTA_EMBED_DOCS
    size_t i;
    for (i=0; docs[i].key; i++) if (!quanta_strcmp(key, docs[i].key)) return docs[i].text;
#else
    (void)key;
#endif
    return NULL;
}
